        self.nextUp = nextUp
        self.templates = templates
        self.lastSession = lastSession
        self.latestPR = latestPR
        self.overload = overload
        self.freshness = freshness
        self.weeklySets = weeklySets
        self.lifts = lifts
        self.month = month
        self.plateaus = plateaus
        self.year = year
        self.block = block
        self.formCue = formCue
        self.loadedBar = loadedBar
        self.strengthRatio = strengthRatio
        self.restDay = restDay
        self.tomorrow = tomorrow
        self.bodyMap = bodyMap
        self.readiness = readiness
        self.partners = partners
        self.active = active
    }
}

/// A personal record just logged; shown for a few seconds in the Live Activity.
public struct PRMoment: Codable, Hashable, Sendable {
    public var exerciseName: String
    public var weightText: String
    public var repsText: String
    public var estimated1RM: Int
    public var deltaKg: Int
    /// The app sends a clearing update at this time.
    public var expiresAt: Date

    public init(
        exerciseName: String,
        weightText: String,
        repsText: String,
        estimated1RM: Int = 0,
        deltaKg: Int = 0,
        expiresAt: Date
    ) {
        self.exerciseName = exerciseName
        self.weightText = weightText
        self.repsText = repsText
        self.estimated1RM = estimated1RM
        self.deltaKg = deltaKg
        self.expiresAt = expiresAt
    }
}

/// One exercise of the running superset.
public struct SupersetMember: Codable, Hashable, Sendable {
    /// "A1"
    public var tag: String
    public var name: String
    /// "10 × 12"
    public var detail: String
    /// This round's set is logged.
    public var isDone: Bool
    public var isCurrent: Bool

    public init(
        tag: String,
        name: String,
        detail: String = "",
        isDone: Bool = false,
        isCurrent: Bool = false
    ) {
        self.tag = tag
        self.name = name
        self.detail = detail
        self.isDone = isDone
        self.isCurrent = isCurrent
    }
}

/// The running superset.
public struct SupersetBrief: Codable, Hashable, Sendable {
    /// "A"
    public var label: String
    /// 1-based.
    public var round: Int
    public var rounds: Int
    public var members: [SupersetMember]

    public init(
        label: String,
        round: Int = 1,
        rounds: Int = 1,
        members: [SupersetMember] = []
    ) {
        self.label = label
        self.round = round
        self.rounds = rounds
        self.members = members
    }
}

/// Plates for the target set.
public struct PlateBrief: Codable, Hashable, Sendable {
    public var totalKg: Double
    public var barKg: Double
    /// Heaviest first.
    public var perSide: [Double]
    public var leftoverKg: Double
    /// "20 + 10 + 2.5"
    public var summary: String

    public init(
        totalKg: Double = 0,
        barKg: Double = 20,
        perSide: [Double] = [],
        leftoverKg: Double = 0,
        summary: String = ""
    ) {
        self.totalKg = totalKg
        self.barKg = barKg
        self.perSide = perSide
        self.leftoverKg = leftoverKg
        self.summary = summary
    }
}

/// A one-tap suggestion for the next set, shown while resting.
public struct CoachTipBrief: Codable, Hashable, Sendable {
    public var title: String
    /// "3 reps in reserve on set 2"
    public var subtitle: String
    public var text: String
    public var suggestedWeightKg: Double
    /// "82.5 kg"
    public var suggestedWeightText: String
    /// "Keep 80"
    public var keepWeightText: String
    /// The set the suggestion applies to.
    public var targetSetID: UUID
    public var targetExerciseID: UUID

    public init(
        title: String = "Felt easy?",
        subtitle: String = "",
        text: String,
        suggestedWeightKg: Double = 0,
        suggestedWeightText: String,
        keepWeightText: String,
        targetSetID: UUID,
        targetExerciseID: UUID
    ) {
        self.title = title
        self.subtitle = subtitle
        self.text = text
        self.suggestedWeightKg = suggestedWeightKg
        self.suggestedWeightText = suggestedWeightText
        self.keepWeightText = keepWeightText
        self.targetSetID = targetSetID
        self.targetExerciseID = targetExerciseID
    }
}

/// The finished workout, shown on the Lock Screen for a few hours.
public struct FinishBrief: Codable, Hashable, Sendable {
    public var workoutName: String
    public var durationMinutes: Int
    public var sets: Int
    /// Tonnes with one decimal ("9.1").
    public var volumeText: String
    public var personalRecordCount: Int
    public var savedToHealth: Bool

    public init(
        workoutName: String,
        durationMinutes: Int = 0,
        sets: Int = 0,
        volumeText: String = "0",
        personalRecordCount: Int = 0,
        savedToHealth: Bool = false
    ) {
        self.workoutName = workoutName
        self.durationMinutes = durationMinutes
        self.sets = sets
        self.volumeText = volumeText
        self.personalRecordCount = personalRecordCount
        self.savedToHealth = savedToHealth
    }
}
